d3.csv("data/stock-descriptions.csv").then(data => {
    // Data processing
    data.forEach(d => {
        d.marketCap = d.marketCap ? +d.marketCap : null;
    });

    const width = 800;
    const height = 600;
    const margin = { top: 20, right: 20, bottom: 20, left: 20 };

    const svg = d3.select("#chart-container")
        .append("svg")
        .attr("width", width)
        .attr("height", height);

    const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
    const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

    // Market Cap scale for bubble radius
    const minRadius = 5;
    const maxRadius = 40;
    const etfRadius = 15;
    const radiusScale = d3.scaleSqrt()
        .domain([0, d3.max(data, d => d.marketCap || 0)])
        .range([minRadius, maxRadius]);

    // Sector positions for force clustering
    const sectorCenters = {};
    sectors.forEach((sector, i) => {
        const angle = (i / sectors.length) * 2 * Math.PI;
        sectorCenters[sector] = {
            x: width / 2 + Math.cos(angle) * 200,
            y: height / 2 + Math.sin(angle) * 200
        };
    });

    const nodes = data.map(d => ({
        ...d,
        radius: d.marketCap ? radiusScale(d.marketCap) : etfRadius,
        x: width / 2 + (Math.random() - 0.5) * 100,
        y: height / 2 + (Math.random() - 0.5) * 100
    }));

    const simulation = d3.forceSimulation(nodes)
        .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.1))
        .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.1))
        .force("collide", d3.forceCollide(d => d.radius + 2))
        .force("center", d3.forceCenter(width / 2, height / 2))
        .on("tick", ticked);

    const tooltip = d3.select("body").append("div")
        .attr("class", "tooltip")
        .style("opacity", 0);

    const bubbles = svg.selectAll(".bubble-group")
        .data(nodes)
        .enter().append("g")
        .attr("class", "bubble-group")
        .on("click", (event, d) => highlight(d.ticker))
        .on("mouseover", function(event, d) {
            // ETFs don't have marketCap, country, or website data - per instruction don't show tooltip
            if (d.marketCap) {
                tooltip.transition().duration(200).style("opacity", .9);
                tooltip.html(`Ticker: ${d.ticker}<br/>Name: ${d['full name']}<br/>Sector: ${d.sector}`)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY - 28) + "px");
            }
        })
        .on("mouseout", function(d) {
            tooltip.transition().duration(500).style("opacity", 0);
        });

    bubbles.append("circle")
        .attr("class", "bubble")
        .attr("r", d => d.radius)
        .attr("fill", d => colorScale(d.sector));

    bubbles.append("text")
        .attr("dy", ".3em")
        .style("text-anchor", "middle")
        .style("font-size", "10px")
        .style("pointer-events", "none")
        .text(d => d.ticker);

    function ticked() {
        bubbles.attr("transform", d => `translate(${d.x},${d.y})`);
    }

    // Legend
    const legend = svg.append("g")
        .attr("transform", "translate(20, 20)");

    sectors.forEach((sector, i) => {
        const legendRow = legend.append("g")
            .attr("transform", `translate(0, ${i * 20})`);
        legendRow.append("rect")
            .attr("width", 15)
            .attr("height", 15)
            .attr("fill", colorScale(sector));
        legendRow.append("text")
            .attr("x", 20)
            .attr("y", 12)
            .text(sector);
    });

    // Table
    const table = d3.select("#table-container").append("table");
    const thead = table.append("thead");
    const tbody = table.append("tbody");

    thead.append("tr")
        .selectAll("th")
        .data(["Ticker symbol", "Full company name", "Sector", "Market cap"])
        .enter().append("th")
        .text(d => d);

    const rows = tbody.selectAll("tr")
        .data(data)
        .enter().append("tr")
        .attr("id", d => "row-" + d.ticker)
        .on("click", (event, d) => highlight(d.ticker));

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d['full name']);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => formatMarketCap(d.marketCap));

    function formatMarketCap(val) {
        if (!val) return "N/A";
        if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
        if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
        if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
        return val.toLocaleString();
    }

    function highlight(ticker) {
        d3.selectAll("tr").classed("highlight", false);
        d3.selectAll(".bubble").style("stroke", "#fff").style("stroke-width", "1px");

        const selectedRow = d3.select("#row-" + ticker);
        selectedRow.classed("highlight", true);
        selectedRow.node().scrollIntoView({ behavior: "smooth", block: "center" });

        bubbles.filter(d => d.ticker === ticker)
            .select("circle")
            .style("stroke", "#000")
            .style("stroke-width", "3px");
    }
});
